const ELEMENT_COLORS={H:0xffffff,C:0x59636f,N:0x4d78ff,O:0xff4b4b,S:0xffd23f,P:0xff8a35,F:0x78d88b,CL:0x47c96b,BR:0xa34b2f,I:0x7d55c7,FE:0xd27a33,CA:0x78c8ff,MG:0x63d7b2,ZN:0x8b9bb3};
const ELEMENT_RADII={H:.55,C:.76,N:.71,O:.66,S:1.05,P:1.07,F:.57,CL:1.02,BR:1.2,I:1.39,FE:1.24,CA:1.76,MG:1.41,ZN:1.22};
const FILE_PATTERN=/\.(pdb|cif|mmcif|mol|sdf|xyz)$/i;

function elementName(value,fallback='C'){const raw=String(value||fallback).replace(/[^A-Za-z]/g,'').toUpperCase();return raw.slice(0,2)==='CL'||raw.slice(0,2)==='BR'||raw.slice(0,2)==='FE'||raw.slice(0,2)==='CA'||raw.slice(0,2)==='MG'||raw.slice(0,2)==='ZN'?raw.slice(0,2):raw[0]||fallback;}
export function parseProteinSpec(source){const raw=String(source??'').trim(),link=raw.match(/!?(?:\[\[)([^\]|#]+)(?:\|[^\]]+)?\]\]/),plain=raw.split(/\r?\n/).map(line=>line.trim()).find(Boolean)||'';if(link||FILE_PATTERN.test(plain)){const path=(link?.[1]||plain).trim();return{kind:'file',value:path,format:path.split('.').pop().toLowerCase()};}const pdb=raw.match(/^(?:pdb(?:id)?\s*:\s*)?([0-9][A-Za-z0-9]{3})$/i);if(pdb)return{kind:'pdb',value:pdb[1].toUpperCase(),format:'pdb'};return{kind:'smiles',value:raw.replace(/^smiles\s*:\s*/i,''),format:'sdf'};}

function parsePdb(text){const atoms=[],serials=new Map(),bonds=[];for(const line of String(text).split(/\r?\n/)){const tag=line.slice(0,6).trim();if(tag==='ATOM'||tag==='HETATM'){const atom={x:Number(line.slice(30,38)),y:Number(line.slice(38,46)),z:Number(line.slice(46,54)),element:elementName(line.slice(76,78),line.slice(12,16))};if(Number.isFinite(atom.x+atom.y+atom.z)){serials.set(Number(line.slice(6,11)),atoms.length);atoms.push(atom);}}else if(tag==='CONECT'){const ids=line.slice(6).trim().split(/\s+/).map(Number),a=serials.get(ids[0]);for(const id of ids.slice(1)){const b=serials.get(id);if(a!==undefined&&b!==undefined&&a<b)bonds.push([a,b]);}}}return{atoms,bonds};}
function tokenizeCifRow(line){return line.match(/'(?:[^']|'')*'|"(?:[^"]|"")*"|\S+/g)?.map(value=>value.replace(/^(['"])(.*)\1$/,'$2'))||[];}
function parseCif(text){const lines=String(text).split(/\r?\n/),atoms=[];for(let i=0;i<lines.length;i++){if(lines[i].trim()!=='loop_')continue;const headers=[];while(/^_atom_site\./.test(lines[i+1]?.trim()||''))headers.push(lines[++i].trim());if(!headers.length)continue;const ix=headers.findIndex(v=>/Cartn_x$/i.test(v)),iy=headers.findIndex(v=>/Cartn_y$/i.test(v)),iz=headers.findIndex(v=>/Cartn_z$/i.test(v)),ie=headers.findIndex(v=>/(?:type_symbol|label_atom_id)$/i.test(v));if(ix<0||iy<0||iz<0)continue;while(++i<lines.length){const line=lines[i].trim();if(!line||line==='#')break;if(line==='loop_'||line.startsWith('_')){i--;break;}const row=tokenizeCifRow(line);if(row.length<headers.length)continue;const atom={x:Number(row[ix]),y:Number(row[iy]),z:Number(row[iz]),element:elementName(row[ie])};if(Number.isFinite(atom.x+atom.y+atom.z))atoms.push(atom);}break;}return{atoms,bonds:[]};}
function parseXyz(text){const lines=String(text).trim().split(/\r?\n/),start=/^\d+$/.test(lines[0]?.trim())?2:0,atoms=[];for(const line of lines.slice(start)){const row=line.trim().split(/\s+/);if(row.length<4)continue;const atom={element:elementName(row[0]),x:Number(row[1]),y:Number(row[2]),z:Number(row[3])};if(Number.isFinite(atom.x+atom.y+atom.z))atoms.push(atom);}return{atoms,bonds:[]};}
function parseMol(text){const lines=String(text).split(/\r?\n/),counts=lines[3]||'',atomCount=Number(counts.slice(0,3)),bondCount=Number(counts.slice(3,6)),atoms=[],bonds=[];for(let i=0;i<atomCount;i++){const line=lines[4+i]||'',atom={x:Number(line.slice(0,10)),y:Number(line.slice(10,20)),z:Number(line.slice(20,30)),element:elementName(line.slice(31,34))};if(Number.isFinite(atom.x+atom.y+atom.z))atoms.push(atom);}for(let i=0;i<bondCount;i++){const line=lines[4+atomCount+i]||'',a=Number(line.slice(0,3))-1,b=Number(line.slice(3,6))-1;if(a>=0&&b>=0&&a<atoms.length&&b<atoms.length)bonds.push([a,b]);}return{atoms,bonds};}
export function parseStructureText(text,format='pdb'){const kind=String(format).toLowerCase();return kind==='cif'||kind==='mmcif'?parseCif(text):kind==='xyz'?parseXyz(text):kind==='mol'||kind==='sdf'?parseMol(text):parsePdb(text);}
function inferBonds(atoms,limit=18000){const bonds=[],grid=new Map(),cell=2.25,key=(x,y,z)=>`${x},${y},${z}`;for(let i=0;i<atoms.length;i++){const a=atoms[i],gx=Math.floor(a.x/cell),gy=Math.floor(a.y/cell),gz=Math.floor(a.z/cell);for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++)for(let dz=-1;dz<=1;dz++)for(const j of grid.get(key(gx+dx,gy+dy,gz+dz))||[]){const b=atoms[j],max=(ELEMENT_RADII[a.element]||.77)+(ELEMENT_RADII[b.element]||.77)+.48,d2=(a.x-b.x)**2+(a.y-b.y)**2+(a.z-b.z)**2;if(d2>.16&&d2<max*max){bonds.push([j,i]);if(bonds.length>=limit)return bonds;}}const bucketKey=key(gx,gy,gz),bucket=grid.get(bucketKey)||[];bucket.push(i);grid.set(bucketKey,bucket);}return bonds;}

export function createProteinExtension(THREE,hooks){let group=null,root=null,state=null,controls=[],anchor=null,placement=false;const W=hooks.width*.58,H=hooks.height*.62,temp=new THREE.Object3D(),up=new THREE.Vector3(0,1,0),mid=new THREE.Vector3(),dir=new THREE.Vector3();
 function preview(block){if(block.querySelector('[data-note-protein-preview]'))return;const canvas=document.createElement('canvas');canvas.width=512;canvas.height=230;const c=canvas.getContext('2d');c.fillStyle='#07111f';c.fillRect(0,0,512,230);c.strokeStyle='#75a7ff';c.lineWidth=7;for(let i=0;i<17;i++){const x=35+i*27,y=115+Math.sin(i*.92)*58;c.beginPath();c.arc(x,y,11,0,Math.PI*2);c.stroke();if(i){const px=35+(i-1)*27,py=115+Math.sin((i-1)*.92)*58;c.beginPath();c.moveTo(px,py);c.lineTo(x,y);c.stroke();}}c.fillStyle='#eef5ff';c.font='700 25px system-ui';c.fillText('3D molecular structure',132,215);const image=new Image();image.dataset.noteProteinPreview='1';image.className='note-protein-image';image.alt='3D molecular structure';image.src=canvas.toDataURL('image/webp',.72);block.replaceChildren(image);}
 function renderBlocks(container){for(const block of container.querySelectorAll('[data-note-protein]'))preview(block);}
 function addControl(action,x,label,color=0x75a7ff){const mesh=new THREE.Mesh(new THREE.CircleGeometry(.014,16),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.94,depthTest:true,depthWrite:true,toneMapped:false}));mesh.position.set(x,-H/2+.023,.055);mesh.userData.noteAction=action;mesh.userData.highlightScale=false;const canvas=document.createElement('canvas');canvas.width=64;canvas.height=64;const c=canvas.getContext('2d');c.fillStyle='#07111f';c.font='bold 31px system-ui';c.textAlign='center';c.textBaseline='middle';c.fillText(label,32,33);const texture=new THREE.CanvasTexture(canvas),icon=new THREE.Mesh(new THREE.PlaneGeometry(.021,.021),new THREE.MeshBasicMaterial({map:texture,transparent:true,depthTest:true,depthWrite:false,toneMapped:false}));icon.position.z=.003;icon.raycast=()=>{};mesh.add(icon);group.add(mesh);controls.push(mesh);hooks.addControl(mesh);}
 function build(data){const atoms=data.atoms.slice(0,8000);if(!atoms.length)throw new Error('No atoms found in this structure.');const bonds=(data.bonds.length?data.bonds:inferBonds(atoms)).filter(([a,b])=>a<atoms.length&&b<atoms.length).slice(0,18000),center=atoms.reduce((v,a)=>v.set(v.x+a.x,v.y+a.y,v.z+a.z),new THREE.Vector3()).multiplyScalar(1/atoms.length),maxRadius=Math.max(...atoms.map(a=>Math.hypot(a.x-center.x,a.y-center.y,a.z-center.z)),1),scale=.17/maxRadius;root=new THREE.Group();const atomGeometry=new THREE.SphereGeometry(1,8,6),atomMaterial=new THREE.MeshStandardMaterial({roughness:.58,metalness:.03,vertexColors:true}),atomMesh=new THREE.InstancedMesh(atomGeometry,atomMaterial,atoms.length),color=new THREE.Color();atoms.forEach((a,i)=>{temp.position.set((a.x-center.x)*scale,(a.y-center.y)*scale,(a.z-center.z)*scale);temp.scale.setScalar(.0065*(ELEMENT_RADII[a.element]||.78));temp.updateMatrix();atomMesh.setMatrixAt(i,temp.matrix);atomMesh.setColorAt(i,color.setHex(ELEMENT_COLORS[a.element]||0xa8b3c7));});atomMesh.instanceMatrix.needsUpdate=true;atomMesh.instanceColor.needsUpdate=true;root.add(atomMesh);if(bonds.length){const bondGeometry=new THREE.CylinderGeometry(.00145,.00145,1,5),bondMaterial=new THREE.MeshStandardMaterial({color:0x9aa7b9,roughness:.72}),bondMesh=new THREE.InstancedMesh(bondGeometry,bondMaterial,bonds.length);bonds.forEach(([ia,ib],i)=>{const a=atoms[ia],b=atoms[ib],pa=new THREE.Vector3((a.x-center.x)*scale,(a.y-center.y)*scale,(a.z-center.z)*scale),pb=new THREE.Vector3((b.x-center.x)*scale,(b.y-center.y)*scale,(b.z-center.z)*scale);mid.copy(pa).add(pb).multiplyScalar(.5);dir.copy(pb).sub(pa);temp.position.copy(mid);temp.quaternion.setFromUnitVectors(up,dir.clone().normalize());temp.scale.set(1,dir.length(),1);temp.updateMatrix();bondMesh.setMatrixAt(i,temp.matrix);});bondMesh.instanceMatrix.needsUpdate=true;root.add(bondMesh);}root.rotation.set(-.18,.45,0);return root;}
 function dispose(){if(anchor?.delete)anchor.delete();anchor=null;placement=false;hooks.disarmPlacement?.();hooks.removeControls(controls);hooks.unregister(group,false);if(group){group.removeFromParent();group.traverse(o=>{o.geometry?.dispose?.();o.material?.map?.dispose?.();o.material?.dispose?.();});}group=root=state=null;controls=[];hooks.layout();}
 async function open(source){dispose();hooks.message('Loading molecular structure…');const spec=parseProteinSpec(source),payload=await hooks.fetchStructure(spec),data=parseStructureText(payload.text,payload.format||spec.format);group=new THREE.Group();group.name='protein-window';const surface=new THREE.Mesh(new THREE.PlaneGeometry(W*.82,H*.76),new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthTest:false,depthWrite:false}));surface.position.z=.015;surface.userData.noteAction='protein-drag';surface.userData.highlightScale=false;surface.userData.preserveOpacity=true;group.add(surface);controls.push(surface);hooks.addControl(surface);group.add(build(data));state={source,spec,scale:1,drags:new Map(),atoms:data.atoms.length,bonds:data.bonds.length};addControl('protein-smaller',-.06,'−');addControl('protein-place',-.02,'⌖',0xffd166);addControl('protein-larger',.02,'+');addControl('protein-reset',.06,'↻');addControl('protein-close',W/2-.016,'×',0xff6b6b);hooks.register(group,W);hooks.message(`Molecule ready · ${data.atoms.length} atoms.`);}
 function beginDrag(event){if(!state||!group)return false;const point=hooks.pinchPoint?.(event.frame,event.inputSource);if(!point)return false;state.drags.set(event.inputSource,{point:group.worldToLocal(point.clone())});if(state.drags.size===2){const values=[...state.drags.values()];state.pinchDistance=values[0].point.distanceTo(values[1].point);state.pinchScale=state.scale;}return true;}
 function endDrag(source){state?.drags?.delete(source);if(state?.drags?.size<2)state.pinchDistance=0;}
 function update(_time,frame,referenceSpace){if(anchor&&frame&&referenceSpace){const pose=frame.getPose(anchor.anchorSpace,referenceSpace);if(pose){const matrix=new THREE.Matrix4().fromArray(pose.transform.matrix);matrix.decompose(group.position,group.quaternion,temp.scale);}}if(!state?.drags?.size||!frame)return;const values=[];for(const[source,drag]of state.drags){const point=hooks.pinchPoint?.(frame,source);if(!point){state.drags.delete(source);continue;}const local=group.worldToLocal(point.clone());values.push({drag,local});}if(values.length>=2){const distance=values[0].local.distanceTo(values[1].local);if(state.pinchDistance>0){state.scale=THREE.MathUtils.clamp(state.pinchScale*distance/state.pinchDistance,.45,2.8);root.scale.setScalar(state.scale);}}else if(values.length===1){const{drag,local}=values[0],dx=local.x-drag.point.x,dy=local.y-drag.point.y;root.rotation.y+=dx*8;root.rotation.x=THREE.MathUtils.clamp(root.rotation.x-dy*8,-1.45,1.45);drag.point.copy(local);}}
 function startPlacement(){if(!group||placement)return;placement=true;state.drags.clear();hooks.unregister(group);hooks.scene.add(group);group.visible=false;hooks.armPlacement?.();hooks.message('Point at a surface and pinch to anchor the molecule.');}
 async function place(hit,event,referenceSpace){if(!placement||!group||!referenceSpace)return false;const pose=hit?.getPose(referenceSpace);if(!pose)return false;const matrix=new THREE.Matrix4().fromArray(pose.transform.matrix),surfacePosition=new THREE.Vector3();matrix.decompose(surfacePosition,temp.quaternion,temp.scale);const cameraPosition=new THREE.Vector3();hooks.camera.getWorldPosition(cameraPosition);group.position.copy(surfacePosition).add(new THREE.Vector3(0,.18,0));group.lookAt(cameraPosition.x,group.position.y,cameraPosition.z);group.visible=true;placement=false;hooks.disarmPlacement?.();if(event?.frame?.createAnchor){try{anchor=await event.frame.createAnchor(new XRRigidTransform({x:group.position.x,y:group.position.y,z:group.position.z},{x:group.quaternion.x,y:group.quaternion.y,z:group.quaternion.z,w:group.quaternion.w}),referenceSpace);}catch(error){console.warn('Protein anchor unavailable; keeping a fixed pose.',error);}}hooks.message('Molecule anchored. Pinch-drag to rotate; use both hands to scale.');return true;}
 function handle(action){if(action==='protein-drag')return true;if(action==='protein-close'){dispose();hooks.message('Molecule closed.');return true;}if(action==='protein-place'){startPlacement();return true;}if(action==='protein-smaller'||action==='protein-larger'){state.scale=THREE.MathUtils.clamp(state.scale*(action==='protein-larger'?1.18:.85),.45,2.8);root.scale.setScalar(state.scale);return true;}if(action==='protein-reset'){state.scale=1;root.scale.setScalar(1);root.rotation.set(-.18,.45,0);return true;}return false;}
 return{renderBlocks,open,dispose,update,handle,beginDrag,endDrag,isPlacementArmed:()=>placement,place};}
